sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* ==========================================================
   CAMPUSMATCH HOW IT WORKS
   WEBSITE + NOW MOBILE APP
   FULL-BLEED SAFE VERSION
========================================================== */

.cm-how-page {
  position: relative;
  display: block;

  width: 100vw !important;
  max-width: 100vw !important;

  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  margin-top: 0 !important;
  margin-bottom: 0 !important;

  min-height: 100vh;
  min-height: 100svh;

  padding: 65px 20px 90px;

  background:
    linear-gradient(
      180deg,
      #FBF8EF 0%,
      #F6F8F1 100%
    ) !important;

  box-shadow:
    0 -60px 0 #FBF8EF,
    0 60px 0 #F6F8F1;

  color: #102E34;

  font-family:
    "DM Sans",
    "Segoe UI",
    sans-serif;

  box-sizing: border-box !important;
  overflow-x: hidden;
}


.cm-how-page,
.cm-how-page *,
.cm-how-page *::before,
.cm-how-page *::after {
  box-sizing: border-box;
}


.cm-how-container {
  position: relative;

  width: 100%;
  max-width: 1200px;

  margin: 0 auto;
}


/* ==========================================================
   HERO
========================================================== */

.cm-how-hero {
  max-width: 720px;
  margin: 0 auto 55px;

  text-align: center;
}


.cm-eyebrow,
.cm-section-eyebrow {
  display: inline-flex;

  padding: 8px 15px;

  margin-bottom: 15px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #15564B;

  font-size: 11px;
  font-weight: 800;

  letter-spacing: .25px;
}


.cm-how-hero h1 {
  margin: 0 0 13px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 47px;
  font-weight: 700;

  letter-spacing: -1.6px;
}


.cm-how-hero p {
  max-width: 650px;

  margin: 0 auto;

  color: #617477;

  font-size: 15px;
  line-height: 1.7;
}


/* ==========================================================
   JOURNEY
========================================================== */

.cm-journey {
  display: grid;

  grid-template-columns:
    1fr 42px
    1fr 42px
    1fr 42px
    1fr;

  align-items: center;

  gap: 8px;

  margin-bottom: 85px;
}


.cm-step-card {
  min-width: 0;
  min-height: 330px;

  padding: 23px;

  border: 1px solid #D2DED8;

  border-radius: 22px;

  background: #FFFFFF;

  box-shadow:
    0 7px 22px rgba(16,78,69,.06);

  transition:
    transform .22s ease,
    box-shadow .22s ease;
}


.cm-step-card:hover {
  transform: translateY(-4px);

  box-shadow:
    0 13px 28px rgba(16,78,69,.10);
}


.cm-step-top {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 25px;
}


.cm-step-number {
  color: #A7B5B0;

  font-family:
    "Plus Jakarta Sans",
    sans-serif;

  font-size: 13px;
  font-weight: 800;
}


.cm-step-icon {
  width: 49px;
  height: 49px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 16px;

  background: #EDF5E9;

  color: #15564B;
}


.cm-step-icon svg {
  width: 25px;
  height: 25px;
}


.cm-step-card h2 {
  margin: 0 0 9px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    sans-serif;

  font-size: 18px;
}


.cm-step-card > p {
  min-height: 74px;

  margin: 0 0 20px;

  color: #6A7C80;

  font-size: 11px;
  line-height: 1.65;
}


.cm-step-points {
  display: flex;
  flex-wrap: wrap;

  gap: 6px;
}


.cm-step-points span {
  padding: 6px 9px;

  border-radius: 999px;

  background: #F3F7F1;

  color: #506267;

  font-size: 8px;
  font-weight: 700;
}


.cm-flow-arrow {
  display: flex;
  align-items: center;
  justify-content: center;

  color: #87BDA8;

  font-size: 26px;
}


/* ==========================================================
   EXPLAINABILITY
========================================================== */

.cm-explain-section {
  padding: 48px;

  display: grid;

  grid-template-columns:
    1fr .9fr;

  align-items: center;

  gap: 55px;

  margin-bottom: 80px;

  border-radius: 30px;

  background: #104E45;

  color: #FFFFFF;

  box-shadow:
    0 15px 40px rgba(16,78,69,.14);
}


.cm-explain-copy .cm-section-eyebrow {
  background:
    rgba(255,255,255,.12);

  color: #BDE8D8;
}


.cm-explain-copy h2 {
  margin: 0 0 14px;

  color: #FFFFFF;

  font-family:
    "Plus Jakarta Sans",
    sans-serif;

  font-size: 31px;
  line-height: 1.25;
}


.cm-explain-copy p {
  max-width: 520px;

  margin: 0;

  color:
    rgba(255,255,255,.70);

  font-size: 12px;
  line-height: 1.7;
}


/* ==========================================================
   SCORE CARD
========================================================== */

.cm-score-card {
  padding: 27px;

  display: grid;

  grid-template-columns:
    150px 1fr;

  align-items: center;

  gap: 25px;

  border:
    1px solid
    rgba(255,255,255,.15);

  border-radius: 23px;

  background:
    rgba(255,255,255,.08);

  backdrop-filter:
    blur(10px);
}


.cm-score-center {
  width: 145px;
  height: 145px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  border:
    12px solid
    #65C3A3;

  border-radius: 50%;

  background:
    rgba(255,255,255,.06);

  text-align: center;
}


.cm-score-center strong {
  color: #FFFFFF;

  font-family:
    "Plus Jakarta Sans",
    sans-serif;

  font-size: 38px;
}


.cm-score-center > span {
  margin-top: -7px;

  color: #BDE8D8;

  font-size: 12px;
}


.cm-score-center small {
  max-width: 80px;

  margin-top: 5px;

  color:
    rgba(255,255,255,.58);

  font-size: 7px;
}


.cm-score-factors {
  display: grid;

  gap: 8px;
}


.cm-score-factors > div {
  padding: 8px 11px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  border-radius: 10px;

  background:
    rgba(255,255,255,.07);
}


.cm-score-factors span {
  color:
    rgba(255,255,255,.72);

  font-size: 9px;
}


.cm-score-factors strong {
  color: #FFFFFF;

  font-size: 10px;
}


/* ==========================================================
   PRIVACY
========================================================== */

.cm-privacy-section {
  margin-bottom: 80px;
}


.cm-section-header {
  max-width: 720px;

  margin: 0 auto 35px;

  text-align: center;
}


.cm-section-header h2 {
  margin: 0 0 12px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    sans-serif;

  font-size: 31px;
  line-height: 1.25;
}


.cm-section-header > p {
  margin: 0;

  color: #687A7E;

  font-size: 13px;
}


.cm-privacy-grid {
  display: grid;

  grid-template-columns:
    repeat(3,1fr);

  gap: 18px;
}


.cm-privacy-card {
  padding: 27px 23px;

  border: 1px solid #D2DED8;

  border-radius: 22px;

  background: #FFFFFF;

  box-shadow:
    0 5px 18px rgba(16,78,69,.05);
}


.cm-privacy-icon {
  width: 53px;
  height: 53px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 18px;

  border-radius: 17px;
}


.cm-privacy-icon svg {
  width: 26px;
  height: 26px;
}


.cm-privacy-icon.public {
  background: #E9F1FF;

  color: #2B5FA8;
}


.cm-privacy-icon.private {
  background: #FDF3DC;

  color: #8D6A1E;
}


.cm-privacy-icon.staff {
  background: #EDF5E9;

  color: #15564B;
}


.cm-privacy-label {
  color: #8B989B;

  font-size: 8px;
  font-weight: 800;

  text-transform: uppercase;

  letter-spacing: .7px;
}


.cm-privacy-card h3 {
  margin: 5px 0 8px;

  color: #104E45;

  font-size: 16px;
}


.cm-privacy-card p {
  margin: 0;

  color: #6B7D80;

  font-size: 10px;
  line-height: 1.65;
}


/* ==========================================================
   FOUND FLOW
========================================================== */

.cm-found-flow {
  padding: 31px 35px;

  display: flex;
  align-items: center;

  gap: 22px;

  margin-bottom: 75px;

  border: 1px solid #D2DED8;

  border-radius: 24px;

  background: #FFFFFF;

  box-shadow:
    0 6px 20px rgba(16,78,69,.06);
}


.cm-found-icon {
  width: 72px;
  height: 72px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 22px;

  background: #EDF5E9;

  color: #15564B;
}


.cm-found-icon svg {
  width: 35px;
  height: 35px;
}


.cm-found-flow span {
  color: #168C70;

  font-size: 9px;
  font-weight: 800;

  text-transform: uppercase;

  letter-spacing: .5px;
}


.cm-found-flow h2 {
  margin: 4px 0 7px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    sans-serif;

  font-size: 21px;
}


.cm-found-flow p {
  margin: 0;

  color: #687A7E;

  font-size: 11px;
  line-height: 1.65;
}


/* ==========================================================
   CTA
========================================================== */

.cm-how-cta {
  padding: 37px 40px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 35px;

  border-radius: 27px;

  background:
    linear-gradient(
      135deg,
      #104E45,
      #156B5B
    );

  color: #FFFFFF;

  box-shadow:
    0 14px 35px rgba(16,78,69,.16);
}


.cm-how-cta > div:first-child > span {
  color: #BDE8D8;

  font-size: 9px;
  font-weight: 800;

  text-transform: uppercase;
}


.cm-how-cta h2 {
  margin: 5px 0;

  color: #FFFFFF;

  font-family:
    "Plus Jakarta Sans",
    sans-serif;

  font-size: 25px;
}


.cm-how-cta p {
  margin: 0;

  color:
    rgba(255,255,255,.68);

  font-size: 11px;
}


.cm-cta-actions {
  display: flex;

  gap: 10px;

  flex-shrink: 0;
}


.cm-cta-actions a {
  padding: 12px 18px;

  border-radius: 999px;

  font-size: 10px;
  font-weight: 800;

  text-decoration: none !important;
}


.cm-cta-primary {
  background: #FFFFFF;

  color: #104E45 !important;
}


.cm-cta-secondary {
  border:
    1px solid
    rgba(255,255,255,.48);

  color: #FFFFFF !important;
}


/* ==========================================================
   TABLET
========================================================== */

@media (max-width: 1000px) {

  .cm-how-page {
    padding:
      56px
      18px
      80px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #F6F8F1;
  }


  .cm-journey {
    grid-template-columns:
      1fr 32px 1fr;

    gap:
      15px 7px;
  }


  .cm-explain-section {
    grid-template-columns:
      1fr;

    gap:
      35px;
  }

}


/* ==========================================================
   MOBILE
========================================================== */

@media (max-width: 700px) {

  .cm-how-page {
    min-height: 100svh;

    padding:
      43px
      15px
      70px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #F6F8F1;
  }


  .cm-how-hero {
    margin-bottom: 38px;
  }


  .cm-how-hero h1 {
    font-size: 34px;
  }


  .cm-how-hero p {
    font-size: 13px;
  }


  .cm-journey {
    display: flex;

    flex-direction: column;

    gap: 10px;

    margin-bottom: 60px;
  }


  .cm-step-card {
    width: 100%;

    min-height: 0;
  }


  .cm-step-card > p {
    min-height: 0;
  }


  .cm-flow-arrow {
    height: 28px;

    transform: rotate(90deg);
  }


  .cm-explain-section {
    padding: 30px 20px;

    margin-bottom: 60px;

    border-radius: 23px;
  }


  .cm-explain-copy h2 {
    font-size: 25px;
  }


  .cm-score-card {
    grid-template-columns: 1fr;
  }


  .cm-score-center {
    margin: 0 auto;
  }


  .cm-privacy-grid {
    grid-template-columns: 1fr;
  }


  .cm-section-header h2 {
    font-size: 25px;
  }


  .cm-found-flow {
    align-items: flex-start;

    flex-direction: column;

    padding: 25px 21px;
  }


  .cm-how-cta {
    align-items: stretch;

    flex-direction: column;

    padding: 29px 22px;
  }


  .cm-cta-actions {
    width: 100%;

    flex-direction: column;
  }


  .cm-cta-actions a {
    width: 100%;

    text-align: center;
  }

}


/* ==========================================================
   SMALL MOBILE
========================================================== */

@media (max-width: 420px) {

  .cm-how-page {
    padding:
      36px
      12px
      62px;
  }


  .cm-how-hero h1 {
    font-size: 30px;
  }


  .cm-how-hero p {
    font-size: 12px;
  }


  .cm-step-card {
    padding: 20px;
  }


  .cm-explain-section {
    padding:
      27px
      17px;
  }


  .cm-score-card {
    padding: 21px;
  }


  .cm-score-center {
    width: 130px;
    height: 130px;

    border-width: 10px;
  }


  .cm-score-center strong {
    font-size: 33px;
  }


  .cm-privacy-card {
    padding:
      24px
      20px;
  }


  .cm-found-flow {
    padding:
      23px
      18px;
  }


  .cm-how-cta {
    padding:
      26px
      18px;
  }

}
